<?php
require __DIR__.'/../vendor/autoload.php';$app=require __DIR__.'/../bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use App\Models\Users;
if(config('database.connections.mysql.database')!=='ketua_test'||!function_exists('pcntl_fork'))throw new RuntimeException('Isolated process-control host required');
function person(){ $u=new Users;$u->fullname=$u->name='Withdrawal race QA';$u->identity=$u->username='race_'.bin2hex(random_bytes(6));$u->email=$u->identity.'@example.test';$u->password=bcrypt('isolated');$u->is_block=0;$u->qa_coin_mode=false;$u->save();return $u;}
$creator=person();$buyer=person();$order=(string)Str::uuid();$oldPolicy=(array)DB::table('earning_policy')->where('id',1)->first();$files=[];
try{
 DB::table('earning_policy')->where('id',1)->update(['withdrawals_enabled'=>true]);DB::table('earner_accounts')->insert(['user_id'=>$creator->id,'status'=>'approved','created_at'=>now(),'updated_at'=>now()]);DB::table('commerce_orders')->insert(['id'=>$order,'user_id'=>$buyer->id,'idempotency_key'=>(string)Str::uuid(),'kind'=>'content','currency_code'=>'UGX','amount_minor'=>10000,'snapshot'=>'{}','status'=>'settled','created_at'=>now()->subDays(8),'updated_at'=>now()]);$sale=DB::table('creator_sales')->insertGetId(['order_id'=>$order,'creator_id'=>$creator->id,'currency_code'=>'UGX','gross_minor'=>10000,'net_minor'=>10000,'creator_bps'=>10000,'status'=>'available','created_at'=>now()->subDays(8),'updated_at'=>now()]);
 foreach([true,false] as $same){$key=(string)Str::uuid();$pids=[];$files=[];
  for($i=0;$i<4;$i++){$path=tempnam('/tmp','ketua-withdraw-');$files[]=$path;DB::disconnect('mysql');$pid=pcntl_fork();if($pid===-1)throw new RuntimeException('Fork failed');if($pid===0){try{auth('app_users')->setUser(Users::findOrFail($creator->id));$r=(new App\Http\Controllers\EarningsController)->request(new Illuminate\Http\Request(['request_key'=>$same?$key:(string)Str::uuid(),'currency_code'=>'UGX','method'=>'mobile_money','destination'=>'Synthetic payout test account','expected_amount_minor'=>10000]));file_put_contents($path,json_encode(['code'=>$r->getStatusCode(),'data'=>$r->getData(true)]));exit(0);}catch(Throwable $e){file_put_contents($path,json_encode(['error'=>get_class($e)]));exit(1);}}$pids[]=$pid;}
  foreach($pids as $pid){pcntl_waitpid($pid,$status);if(pcntl_wexitstatus($status)!==0)throw new RuntimeException('Worker failure');}DB::purge('mysql');$responses=array_map(fn($f)=>json_decode(file_get_contents($f),true),$files);$success=array_filter($responses,fn($r)=>$r['code']===200);
  if(count($success)!==($same?4:1)||DB::table('earning_withdrawals')->where('user_id',$creator->id)->count()!==1||DB::table('withdrawal_events')->whereIn('withdrawal_id',DB::table('earning_withdrawals')->where('user_id',$creator->id)->pluck('id'))->count()!==1||DB::table('creator_sales')->find($sale)->status!=='reserved')throw new RuntimeException('Withdrawal reservation invariant failed');
  echo $same?"PASS Four same-key requests produce one withdrawal\n":"PASS Four different-key requests cannot reserve earnings twice\n";
  DB::table('withdrawal_events')->whereIn('withdrawal_id',DB::table('earning_withdrawals')->where('user_id',$creator->id)->pluck('id'))->delete();DB::table('earning_withdrawals')->where('user_id',$creator->id)->delete();DB::table('creator_sales')->where('id',$sale)->update(['status'=>'available','withdrawal_id'=>null]);foreach($files as $f)unlink($f);$files=[];
 }
 echo "RESULT 2/2 four-worker withdrawal checks passed\n";
}finally{DB::purge('mysql');DB::table('withdrawal_events')->whereIn('withdrawal_id',DB::table('earning_withdrawals')->where('user_id',$creator->id)->pluck('id'))->delete();DB::table('earning_withdrawals')->where('user_id',$creator->id)->delete();DB::table('creator_sales')->where('order_id',$order)->delete();DB::table('commerce_orders')->where('id',$order)->delete();DB::table('earner_accounts')->where('user_id',$creator->id)->delete();Users::whereIn('id',[$creator->id,$buyer->id])->delete();DB::table('earning_policy')->where('id',1)->update($oldPolicy);foreach($files as $f)if(is_file($f))unlink($f);}
